/**
 * ==============================================================================
 * SAR DARK-SLICK CANDIDATE FEATURE EXTRACTION MODULE
 * ==============================================================================
 * Operates on candidates generated by V2 Minimal Morphology.
 * Extracts 17 rigorous, explainable classical-CV features for every candidate:
 *
 * 1.  Pixel area & approximate geographic area (m²)
 * 2.  Bounding box (raster & patch coordinates)
 * 3.  Bounding box width and height
 * 4.  Aspect ratio (W/H and max/min ratio)
 * 5.  Elongation & semi-axes from 2nd central moments covariance matrix
 * 6.  Perimeter (4-connected boundary pixel count)
 * 7.  Perimeter-to-area ratio (P / A)
 * 8.  Centroid (raster, patch, and geodetic coordinates)
 * 9.  Mean VV dB
 * 10. Mean VH dB
 * 11. Median VV dB
 * 12. Median VH dB
 * 13. VV - VH polarimetric difference (mean & median)
 * 14. Local VV contrast / damping relative to ambient ocean collar
 * 15. Local VH contrast / damping relative to ambient ocean collar
 * 16. Boundary / gradient characteristics (Sobel gradient along perimeter)
 * 17. Compactness / circularity (isoperimetric quotient 4πA / P²)
 *
 * Ground truth: DARTIS_2019 ow-0002 Pascal VOC XML
 * Output: backend/data/sentinel-test/validation/candidate_features.json
 * ==============================================================================
 */

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

// File paths
const VAL_DIR = path.resolve(__dirname, '../data/sentinel-test/validation');
const GT_XML_PATH = path.join(VAL_DIR, 'ow-0002.xml');
const CDSE_VV_PATH = path.join(VAL_DIR, 's1a_20190104_vv_db.tif');
const CDSE_VH_PATH = path.join(VAL_DIR, 's1a_20190104_vh_db.tif');
const OUT_FEATURES_JSON = path.join(VAL_DIR, 'candidate_features.json');

// Scene Specifications (DARTIS_2019 ow-0002)
const SCENE_SPEC = {
  patchName: 'S1_20190104_155638_155818_VV_2',
  tag: 'ow-0002-01-000002',
  sceneId: 'S1A_IW_GRDH_1SDV_20190104T155703_20190104T155728_025330_02CD9D_42AF_COG.SAFE',
  acquisitionTime: '2019-01-04T15:56:38Z',
  patchWidth: 640,
  patchHeight: 640,
  corners: {
    ul: { lon: 31.9728158, lat: 31.6193082 },
    ur: { lon: 32.1061271, lat: 31.6387928 },
    br: { lon: 32.0826405, lat: 31.7541920 },
    bl: { lon: 31.9493293, lat: 31.7347075 },
  },
  aoiBbox: [31.949, 31.619, 32.106, 31.754],
  rasterWidth: 512,
  rasterHeight: 512,
  pixelSizeM: 17.2, // ~17.2m per pixel in CDSE resampled 512x512
};

// Physical parameters for V2 Minimal Morphology candidate generation (UNCHANGED)
const PARAMS = {
  windowRadiusPx: 25,
  kSigma: 2.0,
  minDampingDb: 3.5,
  minCandidatePixels: 10,
  nodataDbThreshold: -9000.0,
  oceanMaxVhDb: -20.0,
  oceanMaxVvDb: -10.0,
};

// ==============================================================================
// 1. COORDINATE TRANSFORMATIONS & HELPERS
// ==============================================================================

function patchToGeo(px, py) {
  const { ul, ur, br, bl } = SCENE_SPEC.corners;
  const u = px / SCENE_SPEC.patchWidth;
  const v = py / SCENE_SPEC.patchHeight;

  const topLon = ul.lon + u * (ur.lon - ul.lon);
  const topLat = ul.lat + u * (ur.lat - ul.lat);
  const botLon = bl.lon + u * (br.lon - bl.lon);
  const botLat = bl.lat + u * (br.lat - bl.lat);

  return {
    lon: topLon + v * (botLon - topLon),
    lat: topLat + v * (botLat - topLat),
  };
}

function geoToPatch(lon, lat) {
  const { ul, ur, br, bl } = SCENE_SPEC.corners;
  let u = 0.5, v = 0.5;

  for (let iter = 0; iter < 15; iter++) {
    const topLon = ul.lon + u * (ur.lon - ul.lon);
    const topLat = ul.lat + u * (ur.lat - ul.lat);
    const botLon = bl.lon + u * (br.lon - bl.lon);
    const botLat = bl.lat + u * (br.lat - bl.lat);

    const curLon = topLon + v * (botLon - topLon);
    const curLat = topLat + v * (botLat - topLat);

    const fLon = curLon - lon;
    const fLat = curLat - lat;
    if (Math.abs(fLon) < 1e-8 && Math.abs(fLat) < 1e-8) break;

    const dLon_du = (ur.lon - ul.lon) + v * ((br.lon - bl.lon) - (ur.lon - ul.lon));
    const dLon_dv = botLon - topLon;
    const dLat_du = (ur.lat - ul.lat) + v * ((br.lat - bl.lat) - (ur.lat - ul.lat));
    const dLat_dv = botLat - topLat;

    const det = dLon_du * dLat_dv - dLon_dv * dLat_du;
    if (Math.abs(det) < 1e-12) break;

    u -= (fLon * dLat_dv - fLat * dLon_dv) / det;
    v -= (fLat * dLon_du - fLon * dLat_du) / det;
  }

  return {
    x: u * SCENE_SPEC.patchWidth,
    y: v * SCENE_SPEC.patchHeight,
  };
}

function geoToCdseRaster(lon, lat, bbox, w, h) {
  const [minLon, minLat, maxLon, maxLat] = bbox;
  const x = ((lon - minLon) / (maxLon - minLon)) * w - 0.5;
  const y = ((maxLat - lat) / (maxLat - minLat)) * h - 0.5;
  return { x, y };
}

function cdseRasterToGeo(x, y, bbox, w, h) {
  const [minLon, minLat, maxLon, maxLat] = bbox;
  const lon = minLon + (x + 0.5) * (maxLon - minLon) / w;
  const lat = maxLat - (y + 0.5) * (maxLat - minLat) / h;
  return { lon, lat };
}

// ==============================================================================
// 2. PARSE PASCAL VOC XML GROUND TRUTH
// ==============================================================================

function loadGroundTruth(xmlPath) {
  const xml = fs.readFileSync(xmlPath, 'utf-8');
  const xmin = parseInt(xml.match(/<xmin>([^<]+)<\/xmin>/)[1], 10);
  const ymin = parseInt(xml.match(/<ymin>([^<]+)<\/ymin>/)[1], 10);
  const xmax = parseInt(xml.match(/<xmax>([^<]+)<\/xmax>/)[1], 10);
  const ymax = parseInt(xml.match(/<ymax>([^<]+)<\/ymax>/)[1], 10);

  const cx = (xmin + xmax) / 2;
  const cy = (ymin + ymax) / 2;
  const area = (xmax - xmin) * (ymax - ymin);
  const geoC = patchToGeo(cx, cy);

  const geoTL = patchToGeo(xmin, ymin);
  const geoBR = patchToGeo(xmax, ymax);

  const W = SCENE_SPEC.rasterWidth;
  const H = SCENE_SPEC.rasterHeight;
  const cdseTL = geoToCdseRaster(Math.min(geoTL.lon, geoBR.lon), Math.max(geoTL.lat, geoBR.lat), SCENE_SPEC.aoiBbox, W, H);
  const cdseBR = geoToCdseRaster(Math.max(geoTL.lon, geoBR.lon), Math.min(geoTL.lat, geoBR.lat), SCENE_SPEC.aoiBbox, W, H);
  const cdseC = geoToCdseRaster(geoC.lon, geoC.lat, SCENE_SPEC.aoiBbox, W, H);

  return {
    patchBbox: [xmin, ymin, xmax, ymax],
    patchCentroid: { x: cx, y: cy },
    patchBoxArea: area,
    geoCentroid: geoC,
    cdseBbox: [
      Math.round(Math.min(cdseTL.x, cdseBR.x)),
      Math.round(Math.min(cdseTL.y, cdseBR.y)),
      Math.round(Math.max(cdseTL.x, cdseBR.x)),
      Math.round(Math.max(cdseTL.y, cdseBR.y)),
    ],
    cdseCentroid: { x: Number(cdseC.x.toFixed(2)), y: Number(cdseC.y.toFixed(2)) },
  };
}

// ==============================================================================
// 3. RASTER LOADER (DEFLATE-STRIP SUPPORT)
// ==============================================================================

function readGeoTiffFloat32(filePath, width, height) {
  const buf = fs.readFileSync(filePath);
  const isBE = buf[0] === 0x4d && buf[1] === 0x4d;
  const readUint32 = (off) => isBE ? buf.readUInt32BE(off) : buf.readUInt32LE(off);

  const numStrips = 64;
  const decomp = [];
  for (let i = 0; i < numStrips; i++) {
    const off = readUint32(220 + i * 4);
    const len = readUint32(476 + i * 4);
    decomp.push(zlib.inflateSync(buf.subarray(off, off + len)));
  }

  const raw = Buffer.concat(decomp);
  const floats = new Float32Array(width * height);
  for (let i = 0; i < width * height; i++) {
    floats[i] = isBE ? raw.readFloatBE(i * 4) : raw.readFloatLE(i * 4);
  }
  return floats;
}

// ==============================================================================
// 4. INTEGRAL IMAGE ACCELERATOR
// ==============================================================================

class IntegralImage {
  constructor(width, height) {
    this.w = width;
    this.h = height;
    this.stride = width + 1;
    this.countSat = new Int32Array((width + 1) * (height + 1));
    this.sumSat = new Float64Array((width + 1) * (height + 1));
    this.sqSat = new Float64Array((width + 1) * (height + 1));
  }

  build(data, maskValid) {
    const W = this.w;
    const H = this.h;
    const stride = this.stride;

    for (let y = 0; y < H; y++) {
      let rowCount = 0;
      let rowSum = 0;
      let rowSq = 0;

      for (let x = 0; x < W; x++) {
        const idx = y * W + x;
        const isValid = maskValid[idx] === 1;
        const v = isValid ? data[idx] : 0;

        if (isValid) {
          rowCount += 1;
          rowSum += v;
          rowSq += v * v;
        }

        const currIdx = (y + 1) * stride + (x + 1);
        const topIdx = y * stride + (x + 1);

        this.countSat[currIdx] = this.countSat[topIdx] + rowCount;
        this.sumSat[currIdx] = this.sumSat[topIdx] + rowSum;
        this.sqSat[currIdx] = this.sqSat[topIdx] + rowSq;
      }
    }
  }

  getStats(x1, y1, x2, y2) {
    const stride = this.stride;
    const br = (y2 + 1) * stride + (x2 + 1);
    const tr = y1 * stride + (x2 + 1);
    const bl = (y2 + 1) * stride + x1;
    const tl = y1 * stride + x1;

    const count = this.countSat[br] - this.countSat[tr] - this.countSat[bl] + this.countSat[tl];
    const sum = this.sumSat[br] - this.sumSat[tr] - this.sumSat[bl] + this.sumSat[tl];
    const sq = this.sqSat[br] - this.sqSat[tr] - this.sqSat[bl] + this.sqSat[tl];

    if (count < 10) return { count, mean: 0, stdDev: 0 };

    const mean = sum / count;
    const variance = Math.max(0, (sq / count) - (mean * mean));
    return { count, mean, stdDev: Math.sqrt(variance) };
  }
}

// ==============================================================================
// 5. MORPHOLOGY & COMPONENT EXTRACTION
// ==============================================================================

function erode3x3(mask, w, h) {
  const out = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let keep = 1;
      for (let dy = -1; dy <= 1; dy++) {
        const ny = y + dy;
        if (ny < 0 || ny >= h) { keep = 0; break; }
        for (let dx = -1; dx <= 1; dx++) {
          const nx = x + dx;
          if (nx < 0 || nx >= w || mask[ny * w + nx] === 0) {
            keep = 0;
            break;
          }
        }
        if (!keep) break;
      }
      out[y * w + x] = keep;
    }
  }
  return out;
}

function dilate3x3(mask, w, h) {
  const out = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (mask[y * w + x] === 1) {
        for (let dy = -1; dy <= 1; dy++) {
          const ny = y + dy;
          if (ny < 0 || ny >= h) continue;
          for (let dx = -1; dx <= 1; dx++) {
            const nx = x + dx;
            if (nx < 0 || nx >= w) continue;
            out[ny * w + nx] = 1;
          }
        }
      }
    }
  }
  return out;
}

function extractComponents(mask, w, h) {
  const labels = new Int32Array(w * h);
  let cur = 0;
  const comps = [];

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const idx = y * w + x;
      if (mask[idx] === 1 && labels[idx] === 0) {
        cur++;
        const q = [idx];
        labels[idx] = cur;
        const pxs = [];

        while (q.length > 0) {
          const c = q.pop();
          pxs.push(c);
          const cy = Math.floor(c / w);
          const cx = c % w;

          for (let dy = -1; dy <= 1; dy++) {
            const ny = cy + dy;
            if (ny < 0 || ny >= h) continue;
            for (let dx = -1; dx <= 1; dx++) {
              if (dx === 0 && dy === 0) continue;
              const nx = cx + dx;
              if (nx < 0 || nx >= w) continue;
              const nidx = ny * w + nx;
              if (mask[nidx] === 1 && labels[nidx] === 0) {
                labels[nidx] = cur;
                q.push(nidx);
              }
            }
          }
        }
        comps.push({ label: cur, pixels: pxs, size: pxs.length });
      }
    }
  }
  return comps;
}

// ==============================================================================
// 6. COMPUTATION OF SOBEL GRADIENT FIELD
// ==============================================================================

function computeSobelGradient(vvDb, oceanMask, w, h) {
  const gradMag = new Float32Array(w * h);

  for (let y = 1; y < h - 1; y++) {
    for (let x = 1; x < w - 1; x++) {
      const idx = y * w + x;
      if (oceanMask[idx] === 0) continue;

      const vc = vvDb[idx];
      const getVal = (ny, nx) => {
        const nidx = ny * w + nx;
        return (oceanMask[nidx] === 1 && vvDb[nidx] > PARAMS.nodataDbThreshold) ? vvDb[nidx] : vc;
      };

      const v00 = getVal(y - 1, x - 1);
      const v01 = getVal(y - 1, x);
      const v02 = getVal(y - 1, x + 1);
      const v10 = getVal(y, x - 1);
      const v12 = getVal(y, x + 1);
      const v20 = getVal(y + 1, x - 1);
      const v21 = getVal(y + 1, x);
      const v22 = getVal(y + 1, x + 1);

      // Sobel filters (normalized by 8)
      const gx = (v02 + 2 * v12 + v22 - (v00 + 2 * v10 + v20)) / 8.0;
      const gy = (v20 + 2 * v21 + v22 - (v00 + 2 * v01 + v02)) / 8.0;

      gradMag[idx] = Math.sqrt(gx * gx + gy * gy);
    }
  }

  return gradMag;
}

// ==============================================================================
// 7. FEATURE EXTRACTION FOR EVERY CANDIDATE
// ==============================================================================

function calculateMedian(arr) {
  if (arr.length === 0) return 0;
  const sorted = arr.slice().sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function extractAllFeatures(comp, candidateIndex, vvDb, vhDb, oceanMask, gradMag, w, h, gtInfo) {
  const pixelIndices = comp.pixels;
  const N = pixelIndices.length;

  // 1. Pixel Area & Approx Geographic Area
  const pixelArea = N;
  const pixelAreaM2 = SCENE_SPEC.pixelSizeM * SCENE_SPEC.pixelSizeM; // 295.84 m²
  const geoAreaM2 = Number((N * pixelAreaM2).toFixed(1));
  const geoAreaKm2 = Number((geoAreaM2 / 1e6).toFixed(6));

  // Pixel coordinates analysis
  let minX = w, maxX = 0, minY = h, maxY = 0;
  let sumX = 0, sumY = 0;
  const pixelSet = new Set(pixelIndices);

  const coords = [];
  for (const idx of pixelIndices) {
    const px = idx % w;
    const py = Math.floor(idx / w);
    coords.push({ x: px, y: py });
    if (px < minX) minX = px;
    if (px > maxX) maxX = px;
    if (py < minY) minY = py;
    if (py > maxY) maxY = py;
    sumX += px;
    sumY += py;
  }

  // 2. Bounding Box & 3. Width and Height
  const widthPx = maxX - minX + 1;
  const heightPx = maxY - minY + 1;

  // 4. Aspect Ratio
  const aspectRatioWH = Number((widthPx / heightPx).toFixed(4));
  const majorMinorBboxRatio = Number((Math.max(widthPx, heightPx) / Math.max(1, Math.min(widthPx, heightPx))).toFixed(4));

  // 8. Centroid
  const meanX = sumX / N;
  const meanY = sumY / N;

  // 5. Elongation derived from 2nd Central Moments Covariance Matrix
  // μ_20 = Var(x) + 1/12, μ_02 = Var(y) + 1/12, μ_11 = Cov(x, y)
  let sumSqDiffX = 0, sumSqDiffY = 0, sumProdDiff = 0;
  for (const p of coords) {
    const dx = p.x - meanX;
    const dy = p.y - meanY;
    sumSqDiffX += dx * dx;
    sumSqDiffY += dy * dy;
    sumProdDiff += dx * dy;
  }
  const mu20 = sumSqDiffX / N + 1.0 / 12.0;
  const mu02 = sumSqDiffY / N + 1.0 / 12.0;
  const mu11 = sumProdDiff / N;

  const diffMu = mu20 - mu02;
  const delta = Math.sqrt(diffMu * diffMu + 4 * mu11 * mu11);
  const lambda1 = (mu20 + mu02 + delta) / 2.0; // Major eigenvalue
  const lambda2 = Math.max(1e-6, (mu20 + mu02 - delta) / 2.0); // Minor eigenvalue

  // Semi-major and semi-minor axis lengths (2 * sqrt(lambda))
  const semiMajorAxis = 2.0 * Math.sqrt(lambda1);
  const semiMinorAxis = 2.0 * Math.sqrt(lambda2);
  const elongation = Number(Math.sqrt(lambda1 / lambda2).toFixed(4));
  const eccentricity = Number(Math.sqrt(Math.max(0, 1.0 - lambda2 / lambda1)).toFixed(4));
  const orientationDeg = Number(((0.5 * Math.atan2(2 * mu11, diffMu) * 180.0) / Math.PI).toFixed(2));

  // 6. Perimeter & Boundary Pixels
  // A pixel is on the perimeter if at least one of its 4-neighbors is outside the candidate
  const perimeterPixels = [];
  for (const p of coords) {
    const cx = p.x;
    const cy = p.y;
    const isBoundary =
      cx === 0 || cx === w - 1 || cy === 0 || cy === h - 1 ||
      !pixelSet.has(cy * w + (cx - 1)) ||
      !pixelSet.has(cy * w + (cx + 1)) ||
      !pixelSet.has((cy - 1) * w + cx) ||
      !pixelSet.has((cy + 1) * w + cx);

    if (isBoundary) {
      perimeterPixels.push(cy * w + cx);
    }
  }
  const perimeter = perimeterPixels.length;

  // 7. Perimeter-to-Area Ratio
  const perimeterToAreaRatio = Number((perimeter / N).toFixed(4));

  // 17. Compactness / Circularity (Isoperimetric Quotient 4πA / P²)
  // Circle = 1.0, thin/elongated filaments << 1.0
  const circularity = Number(((4.0 * Math.PI * N) / (perimeter * perimeter)).toFixed(4));

  // Coordinate mapping to Geographic and Patch Space
  const geoC = cdseRasterToGeo(meanX, meanY, SCENE_SPEC.aoiBbox, w, h);
  const geoTL = cdseRasterToGeo(minX, minY, SCENE_SPEC.aoiBbox, w, h);
  const geoBR = cdseRasterToGeo(maxX, maxY, SCENE_SPEC.aoiBbox, w, h);

  const patchC = geoToPatch(geoC.lon, geoC.lat);
  const patchP1 = geoToPatch(geoTL.lon, geoTL.lat);
  const patchP2 = geoToPatch(geoBR.lon, geoBR.lat);

  const patchMinX = Math.round(Math.min(patchP1.x, patchP2.x));
  const patchMaxX = Math.round(Math.max(patchP1.x, patchP2.x));
  const patchMinY = Math.round(Math.min(patchP1.y, patchP2.y));
  const patchMaxY = Math.round(Math.max(patchP1.y, patchP2.y));
  const patchBoxArea = Math.max(1, (patchMaxX - patchMinX) * (patchMaxY - patchMinY));

  // Radiometric Features (VV & VH) — only average over valid pixels (> nodataDbThreshold)
  const vvVals = [];
  const vhVals = [];
  let sumVv = 0;
  let sumVh = 0;

  for (const idx of pixelIndices) {
    const vv = vvDb[idx];
    const vh = vhDb[idx];
    if (vv > PARAMS.nodataDbThreshold) {
      vvVals.push(vv);
      sumVv += vv;
    }
    if (vh > PARAMS.nodataDbThreshold) {
      vhVals.push(vh);
      sumVh += vh;
    }
  }

  // 9. Mean VV dB & 10. Mean VH dB
  const meanVvDb = vvVals.length > 0 ? Number((sumVv / vvVals.length).toFixed(2)) : -20.0;
  const meanVhDb = vhVals.length > 0 ? Number((sumVh / vhVals.length).toFixed(2)) : -28.0;

  // 11. Median VV dB & 12. Median VH dB
  const medianVvDb = vvVals.length > 0 ? Number(calculateMedian(vvVals).toFixed(2)) : meanVvDb;
  const medianVhDb = vhVals.length > 0 ? Number(calculateMedian(vhVals).toFixed(2)) : meanVhDb;

  // 13. VV - VH Polarimetric Difference
  const polarimetricDiffMean = Number((meanVvDb - meanVhDb).toFixed(2));
  const polarimetricDiffMedian = Number((medianVvDb - medianVhDb).toFixed(2));

  // 14. Local VV Contrast / Damping & 15. Local VH Contrast / Damping
  // Measure ambient ocean background in a 5-pixel collar around the candidate
  const collarRingRadius = 5;
  const collarVv = [];
  const collarVh = [];

  const boxMinX = Math.max(0, minX - collarRingRadius);
  const boxMaxX = Math.min(w - 1, maxX + collarRingRadius);
  const boxMinY = Math.max(0, minY - collarRingRadius);
  const boxMaxY = Math.min(h - 1, maxY + collarRingRadius);

  for (let cy = boxMinY; cy <= boxMaxY; cy++) {
    for (let cx = boxMinX; cx <= boxMaxX; cx++) {
      const idx = cy * w + cx;
      if (pixelSet.has(idx) || oceanMask[idx] === 0) continue;
      if (vvDb[idx] > PARAMS.nodataDbThreshold) collarVv.push(vvDb[idx]);
      if (vhDb[idx] > PARAMS.nodataDbThreshold) collarVh.push(vhDb[idx]);
    }
  }

  const ambientMeanVv = collarVv.length > 0
    ? collarVv.reduce((a, b) => a + b, 0) / collarVv.length
    : meanVvDb + 3.5;
  const ambientMeanVh = collarVh.length > 0
    ? collarVh.reduce((a, b) => a + b, 0) / collarVh.length
    : meanVhDb + 2.0;

  const localVvDampingDb = Number((ambientMeanVv - meanVvDb).toFixed(2));
  const localVhDampingDb = Number((ambientMeanVh - meanVhDb).toFixed(2));

  // 16. Boundary / Gradient Characteristics (along perimeter)
  let sumGrad = 0;
  let maxGrad = 0;
  const gradVals = [];

  for (const idx of perimeterPixels) {
    const g = gradMag[idx];
    gradVals.push(g);
    sumGrad += g;
    if (g > maxGrad) maxGrad = g;
  }

  const boundaryGradientMean = Number((sumGrad / Math.max(1, perimeter)).toFixed(3));
  const boundaryGradientMax = Number(maxGrad.toFixed(3));

  let sumGradSqDiff = 0;
  for (const g of gradVals) {
    const diff = g - boundaryGradientMean;
    sumGradSqDiff += diff * diff;
  }
  const boundaryGradientStd = Number(Math.sqrt(sumGradSqDiff / Math.max(1, perimeter)).toFixed(3));

  // Overlap with Pascal VOC Ground Truth Box
  const gt = gtInfo.patchBbox; // [309, 282, 340, 342]
  const interX1 = Math.max(patchMinX, gt[0]);
  const interY1 = Math.max(patchMinY, gt[1]);
  const interX2 = Math.min(patchMaxX, gt[2]);
  const interY2 = Math.min(patchMaxY, gt[3]);

  const interW = Math.max(0, interX2 - interX1);
  const interH = Math.max(0, interY2 - interY1);
  const intersectionArea = interW * interH;
  const unionArea = patchBoxArea + gtInfo.patchBoxArea - intersectionArea;
  const iou = Number((intersectionArea / unionArea).toFixed(4));

  const dx = patchC.x - gtInfo.patchCentroid.x;
  const dy = patchC.y - gtInfo.patchCentroid.y;
  const centroidDistPx = Number(Math.sqrt(dx * dx + dy * dy).toFixed(2));

  return {
    candidateId: `DSC-${String(candidateIndex).padStart(3, '0')}`,
    label: comp.label,

    // Feature 1: Area
    area: {
      pixelArea,
      geoAreaM2,
      geoAreaKm2,
    },

    // Feature 2: Bounding Box
    boundingBox: {
      cdse: { xmin: minX, ymin: minY, xmax: maxX, ymax: maxY },
      patch: { xmin: patchMinX, ymin: patchMinY, xmax: patchMaxX, ymax: patchMaxY },
    },

    // Feature 3: Width and Height
    dimensions: {
      cdseWidthPx: widthPx,
      cdseHeightPx: heightPx,
      patchWidthPx: patchMaxX - patchMinX,
      patchHeightPx: patchMaxY - patchMinY,
    },

    // Feature 4: Aspect Ratio
    aspectRatio: {
      widthToHeight: aspectRatioWH,
      majorToMinorBbox: majorMinorBboxRatio,
    },

    // Feature 5: Elongation (Moments)
    elongation: {
      ratio: elongation,
      eccentricity,
      semiMajorAxisPx: Number(semiMajorAxis.toFixed(2)),
      semiMinorAxisPx: Number(semiMinorAxis.toFixed(2)),
      orientationDeg,
    },

    // Feature 6: Perimeter
    perimeter,

    // Feature 7: Perimeter-to-Area Ratio
    perimeterToAreaRatio,

    // Feature 8: Centroid
    centroid: {
      cdse: { x: Number(meanX.toFixed(2)), y: Number(meanY.toFixed(2)) },
      patch: { x: Number(patchC.x.toFixed(2)), y: Number(patchC.y.toFixed(2)) },
      geo: { lon: Number(geoC.lon.toFixed(6)), lat: Number(geoC.lat.toFixed(6)) },
    },

    // Feature 9 & 10: Mean Radiometry
    radiometryMean: {
      vvDb: meanVvDb,
      vhDb: meanVhDb,
    },

    // Feature 11 & 12: Median Radiometry
    radiometryMedian: {
      vvDb: medianVvDb,
      vhDb: medianVhDb,
    },

    // Feature 13: Polarimetric Difference
    polarimetricDifference: {
      meanVvMinusVhDb: polarimetricDiffMean,
      medianVvMinusVhDb: polarimetricDiffMedian,
    },

    // Feature 14 & 15: Local Contrast / Damping
    localContrast: {
      vvDampingDb: localVvDampingDb,
      vhDampingDb: localVhDampingDb,
      ambientMeanVvDb: Number(ambientMeanVv.toFixed(2)),
      ambientMeanVhDb: Number(ambientMeanVh.toFixed(2)),
    },

    // Feature 16: Boundary / Gradient Characteristics
    boundaryGradient: {
      mean: boundaryGradientMean,
      max: boundaryGradientMax,
      stdDev: boundaryGradientStd,
    },

    // Feature 17: Compactness / Shape Descriptor
    shapeDescriptors: {
      isoperimetricCircularity: circularity,
      boundaryPixelCount: perimeter,
    },

    // Ground Truth Overlap Verification
    groundTruthEvaluation: {
      overlapsGt: intersectionArea > 0,
      intersectionArea,
      iou,
      centroidDistPx,
    },

    // Candidate pixel indices in CDSE raster (for overlay rendering)
    pixels: pixelIndices,
  };
}

// ==============================================================================
// 8. MAIN EXECUTION PIPELINE
// ==============================================================================

async function extractFeaturesPipeline() {
  console.log('================================================================');
  console.log('🔬   SAR DARK-SLICK CANDIDATE FEATURE EXTRACTION MODULE');
  console.log('================================================================\n');

  console.log('📄 Step 1: Ingesting Ground Truth XML (ow-0002)...');
  const gtInfo = loadGroundTruth(GT_XML_PATH);
  console.log(`   GT Patch Bounding Box: [${gtInfo.patchBbox.join(', ')}]`);
  console.log(`   GT Bounding Box Area:  ${gtInfo.patchBoxArea} px²\n`);

  console.log('🛰️ Step 2: Loading Calibrated Sentinel-1 VV & VH Rasters...');
  const w = SCENE_SPEC.rasterWidth;
  const h = SCENE_SPEC.rasterHeight;
  const total = w * h;

  const vvLinear = readGeoTiffFloat32(CDSE_VV_PATH, w, h);
  const vhLinear = readGeoTiffFloat32(CDSE_VH_PATH, w, h);
  console.log(`   Raster Dimensions:     ${w} x ${h} (${total} px)`);

  const vvDb = new Float32Array(total);
  const vhDb = new Float32Array(total);
  const oceanMask = new Uint8Array(total);
  let oceanCount = 0;

  for (let i = 0; i < total; i++) {
    if (vvLinear[i] > 0) {
      vvDb[i] = 10 * Math.log10(vvLinear[i]);
      oceanMask[i] = 1;
      oceanCount++;
    } else {
      vvDb[i] = PARAMS.nodataDbThreshold;
    }

    if (vhLinear[i] > 0) {
      vhDb[i] = 10 * Math.log10(vhLinear[i]);
    } else {
      vhDb[i] = PARAMS.nodataDbThreshold;
    }
  }
  console.log(`   Ocean Valid Pixels:    ${oceanCount} / ${total} (${((oceanCount / total) * 100).toFixed(2)}%)\n`);

  console.log('🧮 Step 3: Running V2 Minimal Morphology Candidate Generator...');
  const sat = new IntegralImage(w, h);
  sat.build(vvDb, oceanMask);

  const R = PARAMS.windowRadiusPx; // 25 px
  const rawDark = new Uint8Array(total);
  let rawCount = 0;

  for (let y = 0; y < h; y++) {
    const y1 = Math.max(0, y - R), y2 = Math.min(h - 1, y + R);
    for (let x = 0; x < w; x++) {
      const idx = y * w + x;
      if (oceanMask[idx] === 0) continue;
      const x1 = Math.max(0, x - R), x2 = Math.min(w - 1, x + R);
      const stats = sat.getStats(x1, y1, x2, y2);
      if (stats.count < 20) continue;

      const damping = stats.mean - vvDb[idx];
      if (damping >= PARAMS.kSigma * stats.stdDev && damping >= PARAMS.minDampingDb) {
        rawDark[idx] = 1;
        rawCount++;
      }
    }
  }

  // 3x3 Closing (Dilation then Erosion) — No pre-erosion!
  const dilated = dilate3x3(rawDark, w, h);
  const cleaned = erode3x3(dilated, w, h);
  const allComps = extractComponents(cleaned, w, h);

  // Retain candidates >= 10 pixels and not touching raster edges (exact V2 logic)
  const retainedComps = [];
  for (const comp of allComps) {
    if (comp.size < PARAMS.minCandidatePixels) continue;
    let touchesEdge = false;
    for (const idx of comp.pixels) {
      const px = idx % w;
      const py = Math.floor(idx / w);
      if (px === 0 || px === w - 1 || py === 0 || py === h - 1) {
        touchesEdge = true;
        break;
      }
    }
    if (!touchesEdge) retainedComps.push(comp);
  }
  console.log(`   Raw Dark Pixels:       ${rawCount}`);
  console.log(`   Raw Regions:           ${allComps.length}`);
  console.log(`   Retained Candidates:   ${retainedComps.length} (size >= ${PARAMS.minCandidatePixels} px, non-edge)\n`);

  console.log('📐 Step 4: Computing Sobel Gradient Field on VV dB Raster...');
  const gradMag = computeSobelGradient(vvDb, oceanMask, w, h);

  console.log('📊 Step 5: Extracting 17 Features for all Retained Candidates...');
  const candidatesFeatures = [];
  let candidateIndex = 1;

  for (const comp of retainedComps) {
    const feat = extractAllFeatures(
      comp,
      candidateIndex++,
      vvDb,
      vhDb,
      oceanMask,
      gradMag,
      w,
      h,
      gtInfo
    );
    candidatesFeatures.push(feat);
  }

  // Check ground truth candidate
  const gtCandidate = candidatesFeatures.find(c => c.groundTruthEvaluation.overlapsGt);
  if (gtCandidate) {
    console.log(`   ✅ Ground-Truth Oil Slick Detected as: ${gtCandidate.candidateId}`);
    console.log(`      Pixel Area:         ${gtCandidate.area.pixelArea} px (${gtCandidate.area.geoAreaM2} m²)`);
    console.log(`      Elongation:         ${gtCandidate.elongation.ratio} (semi-major: ${gtCandidate.elongation.semiMajorAxisPx} px, minor: ${gtCandidate.elongation.semiMinorAxisPx} px)`);
    console.log(`      Circularity:        ${gtCandidate.shapeDescriptors.isoperimetricCircularity} (1.0=circle, thin slick << 1)`);
    console.log(`      Mean VV:            ${gtCandidate.radiometryMean.vvDb} dB | Local Damping: ${gtCandidate.localContrast.vvDampingDb} dB`);
    console.log(`      Mean VH:            ${gtCandidate.radiometryMean.vhDb} dB | Local Damping: ${gtCandidate.localContrast.vhDampingDb} dB`);
    console.log(`      VV - VH Diff:       ${gtCandidate.polarimetricDifference.meanVvMinusVhDb} dB`);
    console.log(`      Boundary Grad Mean: ${gtCandidate.boundaryGradient.mean} dB/px`);
    console.log(`      IoU with GT Box:    ${gtCandidate.groundTruthEvaluation.iou}`);
    console.log(`      Centroid Distance:  ${gtCandidate.groundTruthEvaluation.centroidDistPx} px\n`);
  } else {
    console.log('   ⚠️ WARNING: No candidate overlapped the ground-truth box!\n');
  }

  // Prepare output JSON
  const outputDoc = {
    metadata: {
      module: 'SAR Dark-Slick Candidate Feature Extractor',
      timestamp: new Date().toISOString(),
      benchmarkCase: 'DARTIS_2019 ow-0002',
      gtPatchBbox: gtInfo.patchBbox,
      totalCandidates: candidatesFeatures.length,
      gtCandidateId: gtCandidate ? gtCandidate.candidateId : null,
    },
    candidates: candidatesFeatures,
  };

  fs.writeFileSync(OUT_FEATURES_JSON, JSON.stringify(outputDoc, null, 2));
  console.log(`💾 Saved Candidate Features JSON: ${OUT_FEATURES_JSON}`);
  console.log('Feature extraction complete.\n');

  return outputDoc;
}

if (require.main === module) {
  extractFeaturesPipeline().catch(err => {
    console.error('Fatal feature extraction error:', err);
    process.exit(1);
  });
}

module.exports = {
  extractFeaturesPipeline,
  SCENE_SPEC,
  PARAMS,
};
